import type { ModelWorker, ModelWorkerSession } from '../../../src/model-proposal.ts';
import { spatialFixtureManifest } from './fixture.ts';

type WorkerOptions = { mode?: 'door' | 'region-context';
  inspectInput?: (input: unknown) => void;
  afterScript?: (session: ModelWorkerSession) => Promise<void> };

/** Offline deterministic worker; geometry is generated by the real WASM host API. */
export function spatialFixtureWorker(options: WorkerOptions = {}): ModelWorker {
  return { identity: { provider: 'offline-fixture', model: 'spatial-acceptance-264' }, async run(session) {
    options.inspectInput?.(session.input);
    const source = options.mode === 'region-context'
      ? `return {kind:'clarify',question:'Which door in this region should be widened?',options:[]};`
      : `await model.previewHostedDoorWidth({doorId:${JSON.stringify(spatialFixtureManifest.doorId)},widthMetres:1.1,anchor:'centre'});
        return {kind:'propose',review:{summary:'Widen the ground connecting door to 1100 mm.',
          rationale:'Preserve its physical centre by adjusting the existing host offset.',
          constraints:'Only the door width and existing host offset change.',
          uncertainty:'Authored acceptance fixture requires human review.',
          intent:{interpretation:'Widen one hosted door, keeping its centre.',assumptions:[],certainty:100,
            basis:'Explicit deterministic fixture input.'}}};`;
    const outcome = await session.executeTool('run_model_script', { language: 'typescript', source });
    if (outcome.ok !== true || outcome.done !== true) throw new Error(`Spatial fixture script failed: ${JSON.stringify(outcome)}`);
    await options.afterScript?.(session);
  } };
}

/** Pause after a real result, then return it late when cancellation aborts the session. */
export function spatialWorkerGate() {
  const reached = Promise.withResolvers<void>();
  const released = Promise.withResolvers<void>();
  const finished = Promise.withResolvers<void>();
  return { reached: reached.promise, finished: finished.promise, release: () => released.resolve(),
    async afterScript(session: ModelWorkerSession) {
      const abort = () => released.resolve();
      session.signal.addEventListener('abort', abort, { once: true });
      if (session.signal.aborted) abort();
      reached.resolve();
      try { await released.promise; }
      finally { session.signal.removeEventListener('abort', abort); finished.resolve(); }
    } };
}
